"""Backend tlsfuzzer: kiểm tra kịch bản (validate).un và sanity chưa cài (CT-09)."""from __future__ import annotationsfrom rfcv.backends.tlsfuzzer import TlsfuzzerBackendfrom rfcv.domains.rfc_protocol.schemas import ScenarioProposaldef test_tlsfuzzer_validate() -> None:    backend = TlsfuzzerBackend()    good = ScenarioProposal.model_validate(        {            "requirement_id": "TLS13-0042",            "reach_state": "connected",            "steps": [                {"op": "complete_handshake"},                {"op": "send_raw_record", "args": {"length": "$record.length", "body": "zeros"}},                {"op": "expect", "args": {"within_ms": 2000}},            ],            "bindings": {"record.length": "from_variant"},        }    )    assert backend.validate(good).ok    bad = good.model_copy(update={"bindings": {}})    assert not backend.validate(bad).ok